 dump(OUT/'registries/batch_6_authority_evidence_registry_v1.json',{'schema_version':'1.0.0','items':records}); dump(OUT/'registries/batch_6_claim_relative_impact_registry_v1.json',{'schema_version':'1.0.0','items':impacts})
