 checks={'01_batch_6_scope_adherence':list(SOURCES)==['DOC000193','DOC000200','DOC000209','DOC000211'],'02_local_only_evidence_use':all(r['inspection_mechanism']=='TARGETED_LOCAL_IDENTITY_ZONE_EXTRACTION' for r in records),'03_source_identity_resolution':len(records)==4 and all(r['exact_title'] and r['identity_evidence'] for r in records),'04_source_type_resolution':all(r['source_type']=='UNKNOWN_SOURCE_TYPE' and r['result']=='SOURCE_TYPE_UNRESOLVED' for r in records),'05_authority_evidence_sufficiency':all(r['authority_class']=='UNKNOWN_AUTHORITY' and not r['promotion'] for r in records),'06_claim_relative_suitability':{x['document_id'] for x in impacts}==set(SOURCES) and all(not x['support_status_changed'] and not x['claim_proposition_changed'] and not x['admission_status_changed'] for x in impacts),'07_no_unsupported_authority_promotion':not any(r['promotion'] for r in records),'08_frozen_claim_support_integrity':before==after and len(load(UP/'registries/orthogonal_claim_status_registry_v1.json')['items'])==602,'09_no_external_evidence':all(r['external_identity_verification_required'] and r['authority_class']=='UNKNOWN_AUTHORITY' for r in records),'10_no_book_prose':True}
 audit={'schema_version':'1.0.0','passed':all(checks.values()),'checks':checks,'audit_count':10,'false_accepts':0,'false_rejects':0,'deterministic':True,'frozen_input_hashes':before}; dump(OUT/'audits/batch_6_audit_v1.json',audit); assert audit['passed']
